 Text("${rows.size} queued · ${rows.count{it.getJSONObject("fields").optString("title").isNotBlank()}} with titles · $activeLookups looking up")
 FlowRow{TextButton(onClick={paused=!paused}){Text(if(paused)"Resume lookups" else "Pause lookups")};TextButton(onClick={paused=false;rows.filter{it.getJSONObject("fields").optString("isbn").isNotBlank()&&(it.getJSONObject("fields").optString("title").isBlank()||it.optString("lookupError").isNotBlank())}.forEach{pending.trySend(it)}}){Text("Retry missing details")}}
 val start=(page*25).coerceAtMost((rows.size-1).coerceAtLeast(0));for(i in start until minOf(start+25,rows.size)){val row=rows[i];val fields=row.getJSONObject("fields");val result=preview?.optJSONArray("rows")?.optJSONObject(i);PhonePanel{Text("${i+1}. "+fields.optString("title").ifBlank{fields.optString("isbn").ifBlank{"Manual book"}});if(row.optString("lookupError").isNotBlank())Text(row.optString("lookupError"));result?.let{Text((listOf(it.optString("error"))+(it.optJSONArray("warnings")?.let{a->(0 until a.length()).map{a.optString(it)}}?:emptyList())).filter{it.isNotBlank()}.joinToString(" · "))};FlowRow{TextButton(enabled=!busy,onClick={edit=i}){Text("Edit")};TextButton(enabled=!busy,onClick={rows.removeAt(i);dirty();page=0}){Text("Remove")}};Row(verticalAlignment=Alignment.CenterVertically){Checkbox(row.optBoolean("keepDuplicate"),enabled=!busy,onCheckedChange={rows[i]=JSONObject(row.toString()).put("keepDuplicate",it);dirty()});Text("Keep as additional copy if duplicate")}}}
 FlowRow{TextButton(enabled=page>0,onClick={page--}){Text("Previous rows")};TextButton(enabled=(page+1)*25<rows.size,onClick={page++}){Text("Next rows")}}
 Button(enabled=!busy&&rows.isNotEmpty()&&activeLookups==0,onClick={task{val current=api.refresh();revision=current.optLong("revision");preview=api.tools("catalog-batch/preview",JSONObject().put("rows",JSONArray(rows)).put("revision",revision));confirmed=false;note="Review each row. Fix errors and review again before confirming."}}){Text("Review batch")}
